#!/usr/bin/env bash
# Definitions only: source from FedClip/system. No training is launched here.
WARM_PYTHON=${WARM_PYTHON:-python}
WARM_DATA_ROOT=${WARM_DATA_ROOT:-$(cd ../dataset && pwd)}
WARM_RUN_TAG=${WARM_RUN_TAG:-$(date +%Y%m%d_%H%M%S)_$$}
WARM_RUN_ROOT=${WARM_RUN_ROOT:-../fedfews_native_runs/multi_warmup/$WARM_RUN_TAG}
WARM_GROUP_ROOT=${WARM_GROUP_ROOT:-$WARM_RUN_ROOT/group_files}
WARM_WAIT_SECONDS=${WARM_WAIT_SECONDS:-7200}
WARM_GPU_A_PROJ=${WARM_GPU_A_PROJ:-0}
WARM_GPU_A_AVG=${WARM_GPU_A_AVG:-1}
WARM_GPU_B_PROJ=${WARM_GPU_B_PROJ:-2}
WARM_GPU_B_AVG=${WARM_GPU_B_AVG:-3}
WARM_GPU_C_PROJ=${WARM_GPU_C_PROJ:-4}
WARM_GPU_C_AVG=${WARM_GPU_C_AVG:-5}
# Fresh run/group paths are required for producers (no overwrite). Submit all
# six entries to the existing scheduler; each producer precedes its follower.
# Followers finish their own formation round, then wait without retraining.
# Every run: gr100=101 total rounds; A=101 grouped, B/C=10 Avg +91 grouped.

declare -a COMMANDS=(
"$WARM_PYTHON main.py -algo FedMultiGroupProj -data Cifar100 -m CNN-512 -did $WARM_GPU_A_PROJ -dev cuda -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 0 --target_prox_mu 0 --target_head_mode shared --target_local_schedule joint --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$WARM_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_group_sizes 7,7,6 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_mode group_projection_softmax --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_group_publish '$WARM_GROUP_ROOT/A.json' -exp_name multi_A_full_weights_warm0_projection_seed0 -sfn '$WARM_RUN_ROOT/A_projection/checkpoints' --run_log_dir '$WARM_RUN_ROOT/A_projection/logs' --h5_result_root '$WARM_RUN_ROOT/A_projection/h5' --final_model_root '$WARM_RUN_ROOT/A_projection/final_models'"
"$WARM_PYTHON main.py -algo FedMultiGroupProj -data Cifar100 -m CNN-512 -did $WARM_GPU_A_AVG -dev cuda -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 0 --target_prox_mu 0 --target_head_mode shared --target_local_schedule joint --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$WARM_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_group_sizes 7,7,6 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_mode group_avg_only --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_group_file '$WARM_GROUP_ROOT/A.json' --multi_group_wait_seconds $WARM_WAIT_SECONDS --multi_group_poll_seconds 1 -exp_name multi_A_full_weights_warm0_avg_only_seed0 -sfn '$WARM_RUN_ROOT/A_avg_only/checkpoints' --run_log_dir '$WARM_RUN_ROOT/A_avg_only/logs' --h5_result_root '$WARM_RUN_ROOT/A_avg_only/h5' --final_model_root '$WARM_RUN_ROOT/A_avg_only/final_models'"
"$WARM_PYTHON main.py -algo FedMultiGroupProj -data Cifar100 -m CNN-512 -did $WARM_GPU_B_PROJ -dev cuda -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 0 --target_prox_mu 0 --target_head_mode shared --target_local_schedule joint --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$WARM_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_group_sizes 7,7,6 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_warmup_rounds 10 --multi_group_basis full_weights --multi_group_mode group_projection_softmax --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_group_publish '$WARM_GROUP_ROOT/B.json' -exp_name multi_B_full_weights_warm10_projection_seed0 -sfn '$WARM_RUN_ROOT/B_projection/checkpoints' --run_log_dir '$WARM_RUN_ROOT/B_projection/logs' --h5_result_root '$WARM_RUN_ROOT/B_projection/h5' --final_model_root '$WARM_RUN_ROOT/B_projection/final_models'"
"$WARM_PYTHON main.py -algo FedMultiGroupProj -data Cifar100 -m CNN-512 -did $WARM_GPU_B_AVG -dev cuda -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 0 --target_prox_mu 0 --target_head_mode shared --target_local_schedule joint --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$WARM_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_group_sizes 7,7,6 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_warmup_rounds 10 --multi_group_basis full_weights --multi_group_mode group_avg_only --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_group_file '$WARM_GROUP_ROOT/B.json' --multi_group_wait_seconds $WARM_WAIT_SECONDS --multi_group_poll_seconds 1 -exp_name multi_B_full_weights_warm10_avg_only_seed0 -sfn '$WARM_RUN_ROOT/B_avg_only/checkpoints' --run_log_dir '$WARM_RUN_ROOT/B_avg_only/logs' --h5_result_root '$WARM_RUN_ROOT/B_avg_only/h5' --final_model_root '$WARM_RUN_ROOT/B_avg_only/final_models'"
"$WARM_PYTHON main.py -algo FedMultiGroupProj -data Cifar100 -m CNN-512 -did $WARM_GPU_C_PROJ -dev cuda -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 0 --target_prox_mu 0 --target_head_mode shared --target_local_schedule joint --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$WARM_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_group_sizes 7,7,6 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_warmup_rounds 10 --multi_group_basis delta_history --multi_history_window 10 --multi_group_mode group_projection_softmax --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_group_publish '$WARM_GROUP_ROOT/C.json' -exp_name multi_C_delta_history10_warm10_projection_seed0 -sfn '$WARM_RUN_ROOT/C_projection/checkpoints' --run_log_dir '$WARM_RUN_ROOT/C_projection/logs' --h5_result_root '$WARM_RUN_ROOT/C_projection/h5' --final_model_root '$WARM_RUN_ROOT/C_projection/final_models'"
"$WARM_PYTHON main.py -algo FedMultiGroupProj -data Cifar100 -m CNN-512 -did $WARM_GPU_C_AVG -dev cuda -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 0 --target_prox_mu 0 --target_head_mode shared --target_local_schedule joint --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$WARM_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_group_sizes 7,7,6 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_warmup_rounds 10 --multi_group_basis delta_history --multi_history_window 10 --multi_group_mode group_avg_only --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_group_file '$WARM_GROUP_ROOT/C.json' --multi_group_wait_seconds $WARM_WAIT_SECONDS --multi_group_poll_seconds 1 -exp_name multi_C_delta_history10_warm10_avg_only_seed0 -sfn '$WARM_RUN_ROOT/C_avg_only/checkpoints' --run_log_dir '$WARM_RUN_ROOT/C_avg_only/logs' --h5_result_root '$WARM_RUN_ROOT/C_avg_only/h5' --final_model_root '$WARM_RUN_ROOT/C_avg_only/final_models'"
)

declare -a PREVIEW_COMMANDS=()
for command in "${COMMANDS[@]}"; do PREVIEW_COMMANDS+=("$command --multi_preview"); done
